SELECT DISTINCTROW qrypassiveElemente.[Element Nr], qrypassiveElemente.Elektrolyseur, qrypassiveElemente.Generation, qrypassiveElemente.Position, qrypassiveElemente.[Anoden Nr], qrypassiveElemente.[Kathoden Nr], qrypassiveElemente.[Membran Nr], qrypassiveElemente.Membrantyp, qrypassiveElemente.Gruppe, qrypassiveElemente.[Einschalt Datum], qrypassiveElemente.[Ausschalt Datum], [qryPassiveElemente].[Ausschalt Datum]-[Einschalt Datum] AS GesamtDOL, IIf(IsNull([Ausschalt Datum]),Date()-[Einschalt Datum],Null) AS AktuelleDOL, qrypassiveElemente.Abschaltgrund, qrypassiveElemente.[Anode Coating], qrypassiveElemente.[Anode Electrode], qrypassiveElemente.[Anode Shell], qrypassiveElemente.[Cathode Coating], qrypassiveElemente.[Cathode Electrode], qrypassiveElemente.[Cathode Shell], qrypassiveElemente.[Info Membrane], qrypassiveElemente.Remarks, qrypassiveElemente.[Montage Datum], qrypassiveElemente.[Demontage Datum], qrypassiveElemente.[Elektroden Abstand]
FROM qrypassiveElemente
WHERE (((qrypassiveElemente.[Anoden Nr]) In (SELECT [Anoden Nr] FROM [qryAktiveElemente] As Tmp GROUP BY [Anoden Nr] HAVING Count(*)>1 )))
ORDER BY qrypassiveElemente.[Anoden Nr];
